fn solve(n: i8) -> Vec<char> {
    // We assume n >= 1. For safety, if n <= 0, return an empty vector.
    let len = if n > 0 { n as usize } else { return Vec::new(); };

    // We'll use the repeating pattern "aabb":
    // indices 0,1 -> 'a'; indices 2,3 -> 'b'; then repeat.
    let mut result = Vec::with_capacity(len);
    for i in 0..len {
        if i % 4 < 2 {
            result.push('a');
        } else {
            result.push('b');
        }
    }
    result
}

